{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "National Emission Standards for Hazardous Air Pollutants: Surface Coating of Plastic Parts and Products",
      "criteria": [
        {
          "criterion": "If you apply a material to plastic parts or products (including adhesives) then that activity is within the surface coating source category covered by this subpart.",
          "citations": [
            "40 CFR 63.4481(a)",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "If the affected source uses 378 liters (100 gallons) per year or more of coatings that contain hazardous air pollutants and the facility is a major source (≥9.07 Mg/yr (10 tpy) of any single HAP or ≥22.68 Mg/yr (25 tpy) of combined HAP), then the source is subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "If the specific surface-coating or coating operation meets any of the exclusions listed in §63.4481(c)(1) through (17), then that coating operation is not subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(c)"
          ]
        },
        {
          "criterion": "If the material applied is an \"adhesive\" as defined (a chemical substance applied for the purpose of bonding two surfaces together), then it counts as a coating/covered material under this subpart unless it falls into the specific exceptions listed in the adhesive definition.",
          "citations": [
            "40 CFR 63.4581",
            "40 CFR 63.4481(a)"
          ]
        },
        {
          "criterion": "If the applied material leaves coating solids (a dry film), you must determine organic HAP content per mass of coating solids and compare to the emission limits in §63.4490 using the procedures in §63.4541; if the applied material leaves no coating solids you must still classify the material (coating, thinner/additive, or cleaning material) because thinners/additives/cleaning materials are included in emissions calculations and applicability.",
          "citations": [
            "40 CFR 63.4541",
            "40 CFR 63.4490",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "If you elect the compliant-material option then no coating used may have an organic HAP content exceeding the applicable emission limits and no thinner, additive, or cleaning material used may contain organic HAP as determined under §63.4541.",
          "citations": [
            "40 CFR 63.4491(a)",
            "40 CFR 63.4541"
          ]
        },
        {
          "criterion": "If you do not use the compliant-material option, then you must include all coatings, thinners/additives, and cleaning materials in the emission-rate calculations (with or without add-on controls) and follow the procedures in §63.4561 (emission rate with add-on controls) or §63.4551 (emission rate without add-on controls) to demonstrate compliance with the emission limits in §63.4490.",
          "citations": [
            "40 CFR 63.4491(b)",
            "40 CFR 63.4561",
            "40 CFR 63.4490"
          ]
        },
        {
          "criterion": "If you add six new lines and those changes meet the definition of a new or reconstructed affected source per §63.4482(c) (construction after Dec 4, 2002 or new coating equipment/subcategory not previously performed), then the new/modified lines are subject as new or reconstructed affected source(s).",
          "citations": [
            "40 CFR 63.4482(c)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Describe exactly what the methylene-chloride step does (is it applied to bond parts = adhesive; is it intended to leave a coating/film; is it surface preparation or cleaning?).",
    "Collect material data sheets and manufacturer's formulation data for the methylene chloride material(s): organic HAP content, volatile matter, and solids content.",
    "Determine whether the methylene-chloride application leaves any coating solids/dry film on the substrate (yes/no and measured solids fraction).",
    "Measure or estimate annual consumption (volume and mass) of the methylene-chloride material and all other coatings, thinners, additives, and cleaning materials used in the plastic parts operations (gallons per year and liters per month).",
    "Determine whether total coatings that contain HAP used at the affected source are ≥378 L (100 gal)/yr.",
    "Evaluate facility-level HAP potential to emit (tons per year) to establish whether the facility is a major source (≥10 tpy single HAP or ≥25 tpy total HAP).",
    "Confirm whether the solvent-welding step is performed as part of a coating operation as defined (is it 'application of coating to a substrate' or only a separate bonding operation?).",
    "Check whether the material or product fits any specific exclusion in §63.4481(c)(1)-(17) (e.g., research lab, facility-wide no-organic-HAP use, specific product categories listed).",
    "If treating the material as an adhesive, verify whether it falls into the adhesive exceptions (products used on humans/animals, adhesive tape, contact paper, or adhesive on an inert substrate).",
    "If planning to use the compliant-material option, verify each material's organic HAP content vs. the applicable emission limits in §63.4490 and confirm thinners/additives/cleaning materials contain no organic HAP per §63.4541.",
    "If planning to use emission-rate options, compile monthly records of volumes, densities, mass fraction organic HAP, and coating solids for all relevant materials to run the calculations in §63.4561 and §63.4551.",
    "Document whether the six added lines constitute 'new' or 'reconstructed' per §63.4482(c) and retain records of installation dates and equipment changes.",
    "Assemble process descriptions, photographs or line diagrams showing application method (wipe, brush, spray, dip), capture/enclosure arrangements, and whether emissions are routed to any control devices."
  ]
}

{
  "candidates": [
    {
      "subpart": "A",
      "title": "General Provisions (40 CFR part 63, subpart A)",
      "criteria": [
        {
          "criterion": "If you own or operate a new affected source that is subject to Subpart FFFFFF, then the General Provisions in 40 CFR part 63, subpart A apply to that affected source.",
          "citations": [
            "40 CFR 63.11157(a)"
          ]
        }
      ]
    },
    {
      "subpart": "FFFFFF",
      "title": "Area Source NESHAP for Secondary Copper Smelting",
      "criteria": [
        {
          "criterion": "If you own or operate a new secondary copper smelter that is an area source of HAP emissions (new affected source = constructed or reconstructed on or after October 6, 2006), then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11153(a)",
            "40 CFR 63.11153(b)",
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If your facility processes copper scrap in a blast furnace and converter or uses another pyrometallurgical purification process to produce anode copper from copper scrap, then it meets the definition of 'secondary copper smelter' for this subpart.",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If your facility merely melts recycled copper scrap or copper alloy scrap to produce ingots or for direct use in a manufacturing process (not to produce anode copper via pyrometallurgical purification), then it is not a 'secondary copper smelter' and is not subject to this subpart.",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If you are a research and development facility as defined in CAA section 112(c)(7), then this subpart does not apply to you.",
          "citations": [
            "40 CFR 63.11153(c)"
          ]
        }
      ]
    },
    {
      "subpart": "ZZZZZZ",
      "title": "Area Source NESHAP for Aluminum, Copper, and Other Nonferrous Foundries",
      "criteria": [
        {
          "criterion": "If you own or operate a copper foundry that melts copper or copper-based alloys and pours molten copper into molds to manufacture complex copper castings and you are an area source meeting the material or production criteria in §63.11544(a)(1)–(4), then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11544(a)",
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If your melting operation uses material containing copper foundry HAP (e.g., materials containing lead or nickel ≥0.1% by weight or manganese ≥1.0% by weight), then your foundry is subject to this subpart.",
          "citations": [
            "40 CFR 63.11544(a)(1)",
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If your annual metal melt production (for an existing source) or annual metal melt capacity (for a new source) of copper and other nonferrous metals is at least 600 tons per year, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11544(a)(4)",
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If you are a primary or secondary metal producer that casts molten copper to produce simple shapes such as sows, ingots, bars, rods, billets, or anode copper, then you are not a 'copper foundry' for purposes of this subpart (and the foundry provisions would not apply as a 'copper foundry').",
          "citations": [
            "40 CFR 63.11556"
          ]
        },
        {
          "criterion": "If you are a research or laboratory facility as defined in section 112(c)(7) of the Clean Air Act, then this subpart does not apply to you.",
          "citations": [
            "40 CFR 63.11544(e)"
          ]
        }
      ]
    },
    {
      "subpart": "TTTTTT",
      "title": "Area Source NESHAP for Secondary Nonferrous Metals Processing",
      "criteria": [
        {
          "criterion": "If you own or operate a secondary nonferrous metals processing facility (as defined in §63.11472) that is an area source of HAP emissions, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11462(a)"
          ]
        },
        {
          "criterion": "If you are not a secondary nonferrous metals processing facility, then this subpart does not apply.",
          "citations": [
            "40 CFR 63.11462(a)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Do you process copper scrap using a pyrometallurgical purification process (e.g., smelting/oxidation/reduction) to produce anode copper that is shipped off site for electrolytic refining?",
    "Does the facility cast molten copper into anodes (anode copper) rather than pouring molten copper into molds to make complex castings?",
    "Is the facility classified as a 'secondary copper smelter' under the definition (processes scrap via blast furnace/converter or other pyrometallurgical purification to produce anode copper)?",
    "Is the source an area source of HAPs (facility-wide potential HAP emissions below major-source thresholds per §63.2/state permitting determinations)?",
    "Was construction or reconstruction of the affected source commenced on or after October 6, 2006 (i.e., is it a 'new' affected source for Subpart FFFFFF)?",
    "Do you purchase or use scrap or other materials that contain copper foundry HAP (lead or nickel ≥0.1% by weight, or manganese ≥1.0% by weight) such that the material meets the 'material containing copper foundry HAP' definition?",
    "What is your annual metal melt production (existing) or annual metal melt capacity (new) of copper and other nonferrous metals (tons per year) — is it ≥600 tpy?",
    "Do you operate as a primary or secondary metal producer that produces simple cast shapes or anode copper (sows, ingots, bars, rods, billets, or anode copper) — i.e., not a 'foundry' for Subpart ZZZZZZ?",
    "Does your facility meet the definition of a 'secondary nonferrous metals processing facility' (verify activities against the definition in §63.11472, if applicable)?",
    "Is the facility a research or laboratory facility as defined in CAA section 112(c)(7)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "AAAAA",
      "title": "Lime Manufacturing Plants",
      "criteria": [
        {
          "criterion": "If you own or operate a lime manufacturing plant (an establishment that uses a lime kiln to produce lime product by calcination of limestone, dolomite, shells, or other calcareous substances) that is a major source of HAP, then this subpart applies to the plant's lime kiln(s), associated cooler(s), and processed stone handling operations located at that LMP.",
          "citations": [
            "40 CFR 63.7081(a)",
            "40 CFR 63.7081(a)(1)",
            "40 CFR 63.7082(a)",
            "40 CFR 63.7143"
          ]
        },
        {
          "criterion": "If the material you calcine in the kiln is not limestone/dolomite/shells but is another calcareous substance (for example, calcium carbonate–rich lime mud), then that calcination may still constitute manufacture of lime product and be subject to this subpart.",
          "citations": [
            "40 CFR 63.7081(a)(1)",
            "40 CFR 63.7143"
          ]
        },
        {
          "criterion": "If your plant is not a major source of HAP (i.e., does not emit or have the potential to emit ≥9.07 Mg/yr (10 tpy) of any single HAP or ≥22.68 Mg/yr (25 tpy) of any combination of HAP), then this subpart does not apply to the plant.",
          "citations": [
            "40 CFR 63.7081(a)",
            "40 CFR 63.7081(a)(2)"
          ]
        },
        {
          "criterion": "If the LMP is located at a kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant, or only processes sludge containing calcium carbonate from water softening processes, then this subpart does not apply to that LMP.",
          "citations": [
            "40 CFR 63.7081(a)"
          ]
        },
        {
          "criterion": "If construction or reconstruction of a lime kiln (and, for PM purposes, its associated cooler) began after December 20, 2002 and you met the applicability criteria in §63.7081 at that time, then that kiln is a 'new lime kiln' for PM; and if construction or reconstruction began after January 5, 2023 and you met the applicability criteria in §63.7081 at that time, then that kiln is a 'new lime kiln' for HCl, mercury, organic HAP, and D/F.",
          "citations": [
            "40 CFR 63.7082(b)",
            "40 CFR 63.7082(c)"
          ]
        },
        {
          "criterion": "If you wish to claim that your LMP is an area source (i.e., not a major source) for applicability determinations, then you must measure hydrogen chloride emissions from all lime kilns (subject to permitting authority discretion for idled or essentially identical kilns) using the specified test methods before claiming area source status.",
          "citations": [
            "40 CFR 63.7142(a)",
            "40 CFR 63.7142(c)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions",
      "criteria": [
        {
          "criterion": "If you are subject to subpart AAAAA, then the General Provisions in §§63.1 through 63.16 apply to you as indicated in Table 9 to subpart AAAAA, and where there is overlap subpart AAAAA takes precedence.",
          "citations": [
            "40 CFR 63.7140"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Determine whether the plant is a major source of HAP (calculate actual and potential emissions: any single HAP ≥ 9.07 Mg/yr (10 tpy) or combined HAPs ≥ 22.68 Mg/yr (25 tpy)).",
    "Confirm whether the kiln performs calcination to produce a lime product (calcium oxide, CaO with MgO, or dead-burned dolomite) rather than an unrelated thermal process.",
    "Characterize the kiln feedstock (provide laboratory analysis or documented composition showing whether the material is limestone, dolomite, shells, or other calcareous material such as calcium carbonate–rich lime mud and report % CaCO3 or equivalent).",
    "Document the purpose and fate of the lime produced (on-site reuse only vs. sale/distribution) and whether production meets the definition of 'lime produced' under the subpart.",
    "Verify whether the facility is collocated at one of the listed excluded facility types (kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant) or only processes water softening sludge.",
    "Record construction and reconstruction dates for the kiln and cooler to determine 'new' vs 'existing' status (compare to Dec 20, 2002 and Jan 5, 2023 / July 16, 2024 as referenced in subpart provisions).",
    "Identify whether the kiln has an associated lime cooler, processed stone handling operations, and whether those emission units are part of the plant site subject to the subpart.",
    "If claiming area source status, determine and plan HCl testing for all kilns (or obtain permitting authority agreement for testing fewer kilns) using EPA Method 320, EPA Method 321, or approved ASTM alternatives per §63.7142 and document test dates and results.",
    "Assemble records of control equipment and capture systems (baghouses, fabric filters, DSI, etc.) and routine monitoring/OM&M plans in case subpart AAAAA applies and to prepare for initial compliance demonstrations and notifications."
  ]
}

{
  "candidates": [
    {
      "subpart": "ZZZZ",
      "title": "National Emission Standards for Hazardous Air Pollutants for Stationary Reciprocating Internal Combustion Engines (RICE)",
      "criteria": [
        {
          "criterion": "If you own or operate existing spark-ignition 4SLB or 4SRB stationary RICE with a site rating of more than 500 HP located at an area source of HAP, then the requirements in Table 2d and the operating limitations in Table 2b of this subpart apply to you.",
          "citations": [
            "40 CFR 63.6603(a)"
          ]
        },
        {
          "criterion": "If an existing non-emergency 4SLB or 4SRB stationary RICE with a site rating of more than 500 HP located at an area source met the definition of remote stationary RICE in §63.6675 on the engine's initial compliance date (October 19, 2013), then it is considered a remote stationary RICE under this subpart and subject to the provisions that apply to remote stationary RICE.",
          "citations": [
            "40 CFR 63.6603(f)",
            "40 CFR 63.6675"
          ]
        },
        {
          "criterion": "If an existing non-emergency 4SLB or 4SRB stationary RICE with a site rating of more than 500 HP located at an area source is not a remote stationary RICE and is operated more than 24 hours per calendar year, then the initial compliance demonstration for that engine must be conducted as specified in §63.6630(e) (including the specified performance test runs and measurement requirements).",
          "citations": [
            "40 CFR 63.6630(e)"
          ]
        },
        {
          "criterion": "If you claim remote stationary RICE status for existing non-emergency SI 4SLB or 4SRB engines that met the remote definition on October 19, 2013, then you must evaluate the engine's remote status every 12 months and keep records of the initial and annual status evaluations; if an evaluation shows the engine no longer meets the remote definition you must comply with all requirements for non-remote engines within 1 year of the evaluation.",
          "citations": [
            "40 CFR 63.6603(f)",
            "40 CFR 63.6675"
          ]
        },
        {
          "criterion": "If you own or operate an existing stationary RICE located at an area source of HAP, then you must conduct any initial performance test or other initial compliance demonstration required in Tables 4 and 5 within 180 days after the compliance date specified in §63.6595.",
          "citations": [
            "40 CFR 63.6612(a)",
            "40 CFR 63.6595(a)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions",
      "criteria": [
        {
          "criterion": "If an affected source becomes subject to a relevant standard under this part, then the owner or operator must submit the initial notification required by this section (e.g., the written notification that the source is subject) not later than 120 calendar days after the effective date of the relevant standard or within 120 days after the source becomes subject.",
          "citations": [
            "40 CFR 63.9(b)(2)"
          ]
        },
        {
          "criterion": "If a State requires a notice that contains all the information required in a notification listed in this section, then the owner or operator may submit a copy of the notice sent to the State to the Administrator to satisfy the notification requirements in this section.",
          "citations": [
            "40 CFR 63.9(a)(3)"
          ]
        },
        {
          "criterion": "If you are required to submit a Notification of Compliance Status for a relevant compliance demonstration, then you must submit that notification before the close of business on the 60th day following completion of the relevant compliance demonstration activity (or before the 30th day if the initial compliance demonstration did not include a performance test as provided in the relevant standard).",
          "citations": [
            "40 CFR 63.9(h)(2)(i)",
            "40 CFR 63.9(h)(2)(ii)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm each engine is spark-ignition, four-stroke lean-burn (4SLB) and non-emergency.",
    "Confirm each engine's site-rated brake horsepower (site rating = 800 HP).",
    "Confirm the facility is an area source of HAP (not a major source).",
    "Confirm each engine is an existing engine (construction/reconstruction commenced before the applicable date in §63.6590 for area-source existing engines).",
    "Determine whether each engine met the definition of remote stationary RICE per 40 CFR 63.6675 on the initial compliance date (October 19, 2013) — e.g., verify building counts and distances within 0.25 mile and absence of >4-story buildings as applicable.",
    "Maintain or locate records of the initial and subsequent annual remote-status evaluations (required if claiming remote status).",
    "Determine annual hours of operation for each engine (verify whether >24 hours/year).",
    "Verify whether any initial performance test(s) required by this subpart have already been conducted, and if so whether any such test is less than 2 years old and was conducted using the same methods and accepted by the Administrator per §63.6612(b).",
    "If no prior acceptable performance test exists and testing is required, note the deadline to conduct initial performance tests (within 180 days after the compliance date per §63.6612(a) and the compliance dates in §63.6595).",
    "Verify whether initial notifications and Notification(s) of Compliance Status required under §§63.6645 and 63.9 have been submitted to the State or EPA (including dates and copies).",
    "If claiming remote/work-practice compliance instead of performance testing, verify you satisfied the remote-definition timing requirement (met remote definition on Oct 19, 2013) and have the required annual evaluations and records per §63.6603(f)."
  ]
}

{
  "candidates": [
    {
      "subpart": "CCCCCC",
      "title": "National emission limitations and management practices for Gasoline Dispensing Facilities (GDF)",
      "criteria": [
        {
          "criterion": "if the facility is a gasoline dispensing facility (GDF) located at an area source, then the affected source includes each gasoline storage tank and is subject to this subpart",
          "citations": [
            "40 CFR 63.11111(a)",
            "40 CFR 63.11112(a)"
          ]
        },
        {
          "criterion": "if the fuel in a tank meets the definition of gasoline (Reid vapor pressure ≥ 27.6 kPa) and is used as fuel for internal combustion engines, then that tank is a gasoline storage tank for purposes of this subpart",
          "citations": [
            "40 CFR 63.11132"
          ]
        },
        {
          "criterion": "if the GDF's monthly throughput of gasoline is less than 10,000 gallons, then the facility must comply with the requirements in § 63.11116",
          "citations": [
            "40 CFR 63.11111(b)",
            "40 CFR 63.11116"
          ]
        },
        {
          "criterion": "if the GDF's monthly throughput of gasoline is 10,000 gallons or more, then the facility must comply with the control requirements in § 63.11117",
          "citations": [
            "40 CFR 63.11111(c)",
            "40 CFR 63.11117"
          ]
        },
        {
          "criterion": "if the GDF's monthly throughput of gasoline is 100,000 gallons or more, then the facility must comply with the additional requirements in § 63.11118",
          "citations": [
            "40 CFR 63.11111(d)",
            "40 CFR 63.11118"
          ]
        },
        {
          "criterion": "if a gasoline storage tank has a capacity of less than 250 gallons, then it is not required to comply with the submerged-fill requirements in § 63.11117(b) and must comply only with the requirements in § 63.11116",
          "citations": [
            "40 CFR 63.11117(c)",
            "40 CFR 63.11116"
          ]
        },
        {
          "criterion": "if equipment is used only for the refueling (dispensing) of motor vehicles, then that dispensing equipment is not covered by this subpart (storage tanks remain addressed separately)",
          "citations": [
            "40 CFR 63.11112(a)"
          ]
        },
        {
          "criterion": "if the affected source is subject to this subpart only because it loads gasoline into fuel tanks other than those in motor vehicles, then different recordkeeping start dates and compliance dates specified in § 63.11111(e) and § 63.11113(f) apply",
          "citations": [
            "40 CFR 63.11111(e)",
            "40 CFR 63.11113(f)"
          ]
        }
      ]
    },
    {
      "subpart": "BBBBBB",
      "title": "Area-source standards for bulk gasoline terminals, pipeline breakout stations, pipeline pumping stations, and bulk gasoline plants",
      "criteria": [
        {
          "criterion": "if you own or operate a bulk gasoline terminal, pipeline breakout station, pipeline pumping station, or bulk gasoline plant as identified in § 63.11081(a)(1)–(4), then you are subject to this subpart",
          "citations": [
            "40 CFR 63.11081(a)"
          ]
        },
        {
          "criterion": "if gasoline storage tanks are located at an affected source identified in § 63.11081(a) and those tanks are used only for dispensing gasoline in a manner consistent with tanks located at a gasoline dispensing facility (GDF), then those tanks are not subject to this subpart and must comply with subpart CCCCCC",
          "citations": [
            "40 CFR 63.11081(c)"
          ]
        },
        {
          "criterion": "if an affected source's throughput ever exceeds the applicable throughput threshold for bulk gasoline terminals or bulk gasoline plants, then the affected source will remain subject to requirements for sources above the threshold even if throughput later falls below the threshold",
          "citations": [
            "40 CFR 63.11081(f)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Verify the fuel type in each tank (is the tank storing gasoline as defined by Reid vapor pressure ≥ 27.6 kPa, or diesel/other fuel?)",
    "Record the capacity of each tank (gallons) and date of installation or construction",
    "Confirm whether the tanks are fixed stationary storage tanks at a single physical location treated as one GDF, or portable/other configurations",
    "Determine whether the tanks are used to dispense fuel directly into motor vehicle fuel tanks (on-site company vehicles) or used for other purposes (e.g., loading cargo tanks or non‑motor-vehicle engines)",
    "Calculate monthly throughput for the GDF by summing gasoline loaded into or dispensed from all gasoline storage tanks at the single GDF over the current day plus the previous 364 days and dividing by 12 (to determine if <10,000; ≥10,000; or ≥100,000 gallons thresholds are met)",
    "Check whether any tanks are <250 gallons (or <2,000 gallons and constructed before Jan 10, 2008) for submerged-fill or control exemptions under § 63.11117(c)",
    "Confirm whether the tanks are part of a bulk gasoline terminal/plant/pipeline station (subject to subpart BBBBBB) or are used only in a manner consistent with a GDF (in which case CCCCCC applies per § 63.11081(c))",
    "Determine whether the equipment in question is ‘equipment used for the refueling of motor vehicles’ (dispensing equipment) versus covered storage/tank components",
    "Check construction/startup dates relevant to applicable compliance and recordkeeping dates (e.g., before/after Jan 10, 2008; dates in § 63.11113 and § 63.11111(e))",
    "Identify any enforceable State/local/Tribal rules or permit requirements (e.g., requiring submerged fill) that might affect notification obligations or allow election to comply under those rules",
    "Verify existing recordkeeping and availability of throughput records (records must be available within 24 hours upon request per § 63.11116(b) / § 63.11117(d))",
    "Determine whether you must submit notifications (Initial Notification/Notification of Compliance Status) based on the throughput category and applicable sections (§ 63.11124 and § 63.11117/§ 63.11118 criteria)"
  ]
}

{
  "candidates": [
    {
      "subpart": "LLL",
      "title": "National Emission Standards for Hazardous Air Pollutants for Portland Cement Manufacturing (Subpart LLL)",
      "criteria": [
        {
          "criterion": "If the coal mill uses kiln exhaust gases in its process (i.e., is an in-line coal mill), then the coal mill is an affected source under this subpart (treated as part of the kiln for determining applicable emissions limits).",
          "citations": [
            "40 CFR 63.1340(b)(1)",
            "40 CFR 63.1341"
          ]
